import{o as t,c as o,a as u}from"./app.fcda16e3.js";const s='{"title":"form表单中有bootstrap-switch时怎么提交表单,消失的提交参数","description":"","frontmatter":{},"relativePath":"components/ucharts.md","lastUpdated":1690791380967}',e={},n=u('<h1 id="form表单中有bootstrap-switch时怎么提交表单-消失的提交参数"><a class="header-anchor" href="#form表单中有bootstrap-switch时怎么提交表单-消失的提交参数" aria-hidden="true">#</a> form表单中有bootstrap-switch时怎么提交表单,消失的提交参数</h1><p>form表单中有bootstrap-switch时怎么提交表单 由于有bootstrapSwitch开关控件是一个checkbox，就会导致在提交表单时如果没有被选中（开关打开），则向后台提交时会缺失该input对应的参数。</p><div class="warning custom-block"><p class="custom-block-title">解决方法：</p><p>在开关的input标签下方增加一个hidden的input标签。初始化开关时默认打开，将hidden的input设置为disabled。如果切换为关闭，则将hidden的input中value属性值设置为2，同时取消disabled属性。</p></div><p>前端HTML代码</p><p>复制代码</p><div class="warning custom-block"><p class="custom-block-title">注意事项</p><div class="language-"><pre><code>&lt;div class=&quot;form-group&quot;&gt;\n    &lt;label for=&quot;firstname&quot; class=&quot;col-sm-3 control-label&quot;&gt;是否空闲&lt;/label&gt;\n    &lt;div class=&quot;col-sm-7&quot;&gt;\n        {#  为了解决checkbox不选中时不会传递该参数，每一个checkbox配一个hidden，当checkbox没选择时，设置hidden的值；当checkbox选择时，disable那个hidden #}\n        &lt;input type=&quot;checkbox&quot; class=&quot;form-control&quot; id=&quot;status&quot; name=&quot;status&quot; checked value=&quot;1&quot;&gt;\n        &lt;input type=&quot;hidden&quot; class=&quot;form-control&quot; id=&quot;status2&quot; name=&quot;status&quot; disabled=&quot;disabled&quot;&gt;\n    &lt;/div&gt;\n&lt;/div&gt;\n</code></pre></div></div><p>复制代码 注意：两个input的id值不一样</p><div class="warning custom-block"><p class="custom-block-title">注意事项</p><div class="language-"><pre><code> js代码\n复制代码\n    // 新增时设置状态开关按钮样式\n    $(&quot;#status&quot;).bootstrapSwitch({\n        onText: &quot;启用&quot;,      // 设置ON文本  \n        offText: &quot;禁用&quot;,    // 设置OFF文本  \n        onColor: &quot;success&quot;,// 设置ON文本颜色(info/success/warning/danger/primary)  \n        offColor: &quot;danger&quot;,  // 设置OFF文本颜色 (info/success/warning/danger/primary)  \n        size: &quot;small&quot;,    // 设置控件大小,从小到大  (mini/small/normal/large)\n        onSwitchChange: function (event, state) {\n            console.log(event, state)\n            //监听switch change事件，可以根据状态把相应的业务逻辑代码写在这里\n            let status2Obj = document.getElementById(&quot;status2&quot;)\n            if (state == true) {\n                // 如果开关打开，则将隐藏的input设置为失效\n                status2Obj.setAttribute(&quot;disabled&quot;, &quot;disabled&quot;)\n                // 给checkbox的input框value值设为1\n                $(this).val(&quot;1&quot;);\n            } else {\n                // 如果开关为关闭状态，checkbox为非选中状态，此时序列化form表单时缺少input对应的参数，所以要设置隐藏的的input属性\n                // 设置type=&quot;hidden&quot;的input标签的value=&quot;2&quot;,用来向后端传递\n                status2Obj.setAttribute(&quot;value&quot;, &quot;2&quot;)\n                // 移除disabled属性，否则该input不可用，即不能向后端传递参数\n                status2Obj.removeAttribute(&quot;disabled&quot;)\n            }\n        }\n    });\n</code></pre></div></div>',8);e.render=function(u,s,e,a,i,c){return t(),o("div",null,[n])};export default e;export{s as __pageData};
